import{_ as p,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Pages - October CMS - 4.x","titleTemplate":false,"description":"Define a URL for each page on your website.","frontmatter":{"subtitle":"Define a URL for each page on your website."},"headers":[{"level":2,"title":"Page Configuration","slug":"page-configuration","link":"#page-configuration","children":[{"level":3,"title":"URL Syntax","slug":"url-syntax","link":"#url-syntax","children":[]}]},{"level":2,"title":"Dynamic Pages","slug":"dynamic-pages","link":"#dynamic-pages","children":[{"level":3,"title":"Page Execution Life Cycle","slug":"page-execution-life-cycle","link":"#page-execution-life-cycle","children":[]},{"level":3,"title":"Sending a Custom Response","slug":"sending-a-custom-response","link":"#sending-a-custom-response","children":[]},{"level":3,"title":"Handling Forms","slug":"handling-forms","link":"#handling-forms","children":[]}]},{"level":2,"title":"404 Page","slug":"_404-page","link":"#_404-page","children":[]},{"level":2,"title":"Error Page","slug":"error-page","link":"#error-page","children":[]},{"level":2,"title":"Setting the Page Title","slug":"setting-the-page-title","link":"#setting-the-page-title","children":[{"level":3,"title":"Using Page Properties","slug":"using-page-properties","link":"#using-page-properties","children":[]},{"level":3,"title":"Using Placeholder Variables","slug":"using-placeholder-variables","link":"#using-placeholder-variables","children":[]}]},{"level":2,"title":"Injecting Page Assets Programmatically","slug":"injecting-page-assets-programmatically","link":"#injecting-page-assets-programmatically","children":[]}],"relativePath":"4.x/cms/themes/pages.md","filePath":"4.x/cms/themes/pages.md"}'),u={name:"4.x/cms/themes/pages.md"};function r(d,a,g,k,h,m){const e=n("pre-heading"),t=n("post-heading");return o(),c("div",null,[s(e),a[0]||(a[0]=l("h1",null,"Pages",-1)),s(t),a[1]||(a[1]=i(`<p>Every website serves up at least one page and in October CMS, a page is represented with page template. Page template files reside in the <strong>pages</strong> directory in your theme. Page file names do not affect the routing, but it&#39;s a good idea to name your pages according to the page&#39;s function. The files should have the <strong>htm</strong> extension.</p><p>The Configuration and Twig template sections are required for pages, but the PHP section is optional. Below, you can see the simplest home page example.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="page-configuration"><a href="#page-configuration" class="header-anchor">#</a> Page Configuration</h2><p>Page configuration is defined in the configuration Section of the page template file. The page configuration defines the page parameters, required for the routing and rendering the page and its <a href="./components.html">Components</a>, which are explained in another article. The following configuration parameters are supported for pages:</p><div class="table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><strong>url</strong></td><td>the page URL, required. The URL syntax is described below.</td></tr><tr><td><strong>title</strong></td><td>the page title, required.</td></tr><tr><td><strong>layout</strong></td><td>the page <a href="./layouts.html">layout</a>, optional. If specified, should contain the name of the layout file, without extension, for example: <code>default</code>.</td></tr><tr><td><strong>description</strong></td><td>the page description for the back-end interface, optional.</td></tr><tr><td><strong>hidden</strong></td><td>hidden pages are accessible only by logged-in back-end users, optional.</td></tr></tbody></table></div><h3 id="url-syntax"><a href="#url-syntax" class="header-anchor">#</a> URL Syntax</h3><p>The page URL is defined with the <strong>url</strong> configuration parameter. URLs should start with the forward slash character, and can contain parameters. URLs without parameters are fixed and strict. In the following example, the page URL is <code>/blog</code>.</p><div class="custom-block tip"><p>The page URL is case-insensitive by default.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div></div><p>URLs with parameters are more flexible. A page with the URL pattern defined in the following example would be displayed for any address like <code>/blog/post/something</code>. URL parameters can be accessed by October components or from the page PHP code section.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id</span>&quot;</span>
</code></pre></div><p>This is how you can access the URL parameter from the page&#39;s PHP section (see the Dynamic Pages section for more details).</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$postId</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code></code></pre></div></div><p>Parameter names should be compatible with PHP variable names. To make a parameter optional, add a question mark after its name:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id?</span>&quot;</span>
</code></pre></div><p>Parameters in the middle of the URL cannot be optional. In the next example, the <code>:post_id</code> parameter is marked as optional, but is processed as required.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:post_id?/comments</span>&quot;</span>
</code></pre></div><p>Optional parameters can have default values which are used as fallback values in case the real parameter value is not presented in the URL. Default values cannot contain any asterisks, pipe symbols, or question marks. The default value is specified after the <strong>question mark</strong>. In the next example, the <code>category_id</code> parameter would be <code>10</code> for the URL <code>/blog/category</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/category/:category_id?10</span>&quot;</span>
</code></pre></div><p>You can also use regular expressions to validate parameters. To add a validation expression, add a pipe symbol after the parameter name, or a question mark, and specify the expression. The forward slash symbol is not allowed in these expressions. Examples:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$/comments&quot; ; this will match /blog/10/comments</span>

<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$&quot; ; this will match /blog/3</span>

<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_name?|^[a-z0-9\\-]+$&quot; ; this will match /blog/my-blog-post</span>
</code></pre></div><p>It is possible to use a special <em>wildcard</em> parameter by placing an <strong>asterisk</strong> after the parameter. Unlike regular parameters, wildcard parameters can match one or more URL segments. A URL can only ever contain a single wildcard parameter, cannot use regular expressions, or be followed by an optional parameter.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:category*/:slug</span>&quot;</span>
</code></pre></div><p>Wildcard parameters themselves can be made optional by preceding the asterisk with the <code>?</code> character however.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:slug?*</span>&quot;</span>
</code></pre></div><p>For example, a URL like <code>/color/:color/make/:make*/edit</code> will match <code>/color/brown/make/volkswagen/beetle/retro/edit</code> and extract the following parameter values:</p><ul><li>color: <code>brown</code></li><li>make: <code>volkswagen/beetle/retro</code></li></ul><div class="custom-block tip"><p>Subdirectories do not affect page URLs - the URL is defined only with the <strong>url</strong> parameter.</p></div><h2 id="dynamic-pages"><a href="#dynamic-pages" class="header-anchor">#</a> Dynamic Pages</h2><p>Inside the Twig section of a page template, you can use any <a href="./../../markup/templating.html">functions, filters, and tags provided by October CMS</a>. Any dynamic page requires <strong>variables</strong> and variables may be prepared by the page or layout PHP section, or by <a href="./components.html">Components</a>. In this article, we describe how to prepare variables in the PHP section.</p><h3 id="page-execution-life-cycle"><a href="#page-execution-life-cycle" class="header-anchor">#</a> Page Execution Life Cycle</h3><p>There are special functions that can be defined in the PHP section of pages and layouts: <code>onInit</code>, <code>onStart</code>, and <code>onEnd</code>. The <code>onInit</code> function is executed when all components are initialized and before AJAX requests are handled. The <code>onStart</code> function is executed during the beginning of the page execution. The <code>onEnd</code> function is executed before the page is rendered and after the page <a href="./components.html">components</a> are executed. In the <code>onStart</code> and <code>onEnd</code> functions, you can inject variables into the Twig environment. Use the <code>$this</code> with array notation to pass variables to the page.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;hello&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;Hello world!&quot;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hello <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The next example is more complicated. It shows how to load a blog post collection from the database, and display on the page (the <code>Acme\\Blog</code> plugin is imaginary).</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Post</span><span class="token punctuation">;</span>

<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>Latest posts<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content <span class="token delimiter punctuation">}}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>The default variables and Twig extensions provided by October CMS are described in the <a href="./../../markup/templating.html">Markup Guide</a>. The sequence that the handlers are executed in is described by the <a href="./layouts.html">Dynamic Layouts section</a>.</p><h3 id="sending-a-custom-response"><a href="#sending-a-custom-response" class="header-anchor">#</a> Sending a Custom Response</h3><p>All methods defined in the execution life cycle have the ability to halt the process and return a response - simply return a response from the life cycle function. The example below will not load any page contents, and instead return the string <em>Hello world!</em> to the browser:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>A more useful example might be triggering a redirect using the <code>Redirect</code> facade:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://google.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="handling-forms"><a href="#handling-forms" class="header-anchor">#</a> Handling Forms</h3><p>You can handle standard forms with handler methods defined in the page or layout PHP section (handling the AJAX requests is explained in the <a href="./../../ajax/introduction.html">AJAX Framework</a> article). Use the <code>form_open()</code> <a href="./../../markup/function/form.html">Twig function</a> to define a form that refers to an event handler.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Please enter a string<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value<span class="token punctuation">&quot;</span></span><span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Last submitted value: {{ lastValue }}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <code>onHandleForm</code> function can be defined in the page or layout PHP section.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onHandleForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;lastValue&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The handler loads the value with the <code>post</code> function and initializes the page&#39;s <code>lastValue</code> attribute variable which is displayed below the form in the first example.</p><div class="custom-block tip"><p>If a handler with the same name is defined in the page layout, the page, and a <a href="./components.html">page component</a>, October CMS will execute the page handler. If a handler is defined in a component and a layout, the layout handler will be executed. The handler precedence is: page, layout, component.</p></div><p>If you want to refer to a handler defined in a specific component, use the component&#39;s name or alias in the handler reference:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myComponent::onHandleForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="_404-page"><a href="#_404-page" class="header-anchor">#</a> 404 Page</h2><p>If the theme contains a page with the URL <code>/404</code>, it is displayed when the system can&#39;t find a requested page.</p><h2 id="error-page"><a href="#error-page" class="header-anchor">#</a> Error Page</h2><p>By default, any errors will be shown with a detailed error page containing the file contents, line number, and stack trace where the error occurred. You can display a custom error page by setting the configuration value <code>debug</code> to <strong>false</strong> in the <code>config/app.php</code> script, and creating a page with the URL <code>/error</code>.</p><h2 id="setting-the-page-title"><a href="#setting-the-page-title" class="header-anchor">#</a> Setting the Page Title</h2><p>Setting the page title can be done inside PHP, using the Page Object, or inside Twig, using the <a href="./../../markup/tag/placeholder.html">placeholder tag</a>.</p><h3 id="using-page-properties"><a href="#using-page-properties" class="header-anchor">#</a> Using Page Properties</h3><p>The properties of a page can be accessed in the PHP code section or <a href="./components.html">Components</a> by referencing <code>$this-&gt;page</code>. The following sets the <code>meta_title</code> attribute to a new value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token operator">-&gt;</span><span class="token property">meta_title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;A different page title&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>{{ this.page }}</code> variable can be accessed in Twig using the <code>this.page</code> variable. For example, to return the <code>meta_title</code> attribute inside a layout.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>page<span class="token punctuation">.</span>meta_title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>More information on <code>this.page</code> can be found in <a href="./../../markup/property/this-page.html">the Markup guide</a>.</p></div><h3 id="using-placeholder-variables"><a href="#using-placeholder-variables" class="header-anchor">#</a> Using Placeholder Variables</h3><p>The <code>{% put %}</code> tag allows you to store a value inside a placeholder variable. The following sets the <code>pageTitle</code> variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> pageTitle <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>Yet another page title<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <code>placeholder()</code> Twig function is used to access the variable inside the layout.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>pageTitle<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>A default value (second argument) can be supplied as a fallback.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>pageTitle<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> this<span class="token punctuation">.</span>page<span class="token punctuation">.</span>meta_title<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>More information on the placeholder tag can be found in <a href="./../../markup/tag/placeholder.html">placeholder tag article</a>.</p></div><h2 id="injecting-page-assets-programmatically"><a href="#injecting-page-assets-programmatically" class="header-anchor">#</a> Injecting Page Assets Programmatically</h2><p>If needed, you can inject assets (CSS and JavaScript files) into pages with the controller&#39;s <code>addCss</code> and <code>addJs</code> methods. It could be done in the <code>onStart</code> function defined in the PHP section of a page or <a href="./layouts.html">layout template</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>If the path specified in the <code>addCss</code> and <code>addJs</code> method argument begins with a slash (/), it will be relative to the website root. If the asset path does not begin with a slash, it is relative to the theme.</p><p>Injected assets can be combined by passing them as an array:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/css/goodbye.css&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/js/nav.js&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>LESS and SCSS assets can be injected and compiled using the combiner.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/less/base.less&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The second argument of <code>addCss</code> and <code>addJs</code> allows you to provide additional attributes to your injected assets:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/js/nav.js&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;defer&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In order to output the injected assets on pages or <a href="./layouts.html">layouts</a>, use the <code>{% styles %}</code> and <code>{% scripts %}</code> tags. Example:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">styles</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">scripts</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>More information on <code>{% styles %}</code> and <code>{% scripts %}</code> tags can be found at <a href="./../../markup/tag/placeholder.html">the Markup guide</a>.</p></div>`,83))])}const b=p(u,[["render",r]]);export{v as __pageData,b as default};
